119	    setShortcutState(newShortcut);
120	    // Clear content search filter when selecting a shortcut (issue #5462)
121	    if (newShortcut !== undefined) {
122	      setFiltersState((prev) => prev.filter((f) => f.factor !== "contentSearch"));
123	    }
124	  }, []);
125	
126	  const hasFilter = useCallback((filter: MemoFilter) => filters.some((f) => getMemoFilterKey(f) === getMemoFilterKey(filter)), [filters]);
